/// Native replay implementations for memory bindings.
#[inline]
fn destack_memory_advise_advise_replay(
    context: &RuntimeCallContext,
    address: u64,
    length: u64,
    advice: u32,
) -> RuntimeResult<()> {
    let _ = (&address, &length, &advice);

    context.replay().run_binding(
        MEMORY_ADVISE_ADVISE,
        || unsafe { platform_native::destack_memory_advise(context, address, length, advice) },
        |result| {
            if let Ok(()) = result {
                let result_replay = ();
                let payload = MemoryAdviseAdviseReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    MemoryAdviseAdviseReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

