#[inline]
fn destack_memory_map_reserve_replay(
    context: &RuntimeCallContext,
    out: *mut MemoryRange,
    length: u64,
    flags: u32,
) -> RuntimeResult<()> {
    let _ = (&length, &flags);

    context.replay().run_binding(
        MEMORY_MAP_RESERVE,
        || unsafe { platform_native::destack_memory_reserve(context, out, length, flags) },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_replay_address = result_value.address;
                let result_replay_length = result_value.length;
                let result_replay = MemoryRange {
                    address: result_replay_address,
                    length: result_replay_length,
                };
                let payload = MemoryMapReserveReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    MemoryMapReserveReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_address = value.address;
                    let value_native_length = value.length;
                    let value_native = MemoryRange {
                        address: value_native_address,
                        length: value_native_length,
                    };
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

