/// VM replay implementations for memory bindings.
#[inline]
fn destack_memory_advise_advise_vm_replay(
    runtime: &RuntimeCallContext,
    context: &mut vm::RuntimeContext<'_>,
    address: u64,
    length: u64,
    advice: u32,
) -> RuntimeResult<vm::Value> {
    let result = runtime.replay().run_binding_with_context(
        MEMORY_ADVISE_ADVISE,
        context,
        |context| platform_vm::destack_memory_advise(runtime, context, address, length, advice),
        |context, result| {
            let _ = &context;
            if let Ok(()) = result {
                let result_replay = ();
                let payload = MemoryAdviseAdviseReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    MemoryAdviseAdviseReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    );
    let result = encode_destack_memory_advise_advise_result(context, result)?;
    Ok(result)
}

